#!/usr/bin/env node
// Generates the SPA-EMBEDDED version of the Legends Bracket page, for
// index.html's #page-bracket (a real page inside the premium app, reached
// via navigate('bracket') from the nav-dropdown -- see that file's
// nav-dropdown <li id="tab-bracket">). This is a SEPARATE artifact from
// worker/bracket-page.js (the standalone /bracket page for free/logged-out
// browsing, generated by gen-bracket-page.cjs) -- same source prototype,
// two different shells, because the SPA already provides its own top nav,
// account menu and page-switching chrome that the standalone page has to
// build for itself.
//
// Source of truth is still prototypes/legends-bracket.html. Edit that file,
// not the generated output below.
//
// SAFETY MODEL (why this is safe to splice into a 147K-line production
// file): every CSS selector below gets "#page-bracket " prepended, so NONE
// of it can affect anything outside that page div, however generic the
// class name (h1, .vs, .sub, .seed, ...) -- verified zero collisions today,
// but scoping makes that not matter going forward either. The prototype's
// own color tokens (--line, --paper, --surface-2, --good, --bad,
// --accent-2, --on-accent, --shadow) are NOT renamed throughout the CSS;
// instead they're aliased ONCE as custom properties on #page-bracket itself
// (see ALIAS_CSS below), inherited by everything under it -- index.html's
// own --bg/--border/--text/--muted/--accent/--surface/--surface2/--card
// already carry the exact same values (verified byte-for-byte against
// index.html's :root), so this is a real alias, not a re-skin. IDs
// (col-qf, submitBtn, results, ...) are left as the prototype's own name --
// also verified against index.html with zero collisions -- rather than
// mechanically prefixed, because a hand-typed prefix sweep across the JS's
// getElementById calls is a much easier place to introduce a silent typo
// than the mechanical selector-scoping below.
const fs = require("fs");
const path = require("path");

const SRC = path.join(__dirname, "..", "prototypes", "legends-bracket.html");
const TARGET = path.join(__dirname, "..", "index.html");

const src = fs.readFileSync(SRC, "utf8");

function between(s, startMarker, endMarker) {
  const i = s.indexOf(startMarker);
  if (i === -1) throw new Error("marker not found: " + startMarker);
  const from = i + startMarker.length;
  const j = s.indexOf(endMarker, from);
  if (j === -1) throw new Error("end marker not found: " + endMarker);
  return s.slice(from, j);
}

// ---- 1. Extract the raw <style> block ----
const rawCss = between(src, "<style>", "</style>");

// ---- 2. Strip the parts an embedded page must not carry: :root (would
// clobber index.html's real :root -- custom properties are NOT scoped by
// where the <style> tag sits in the DOM), the universal box-sizing reset,
// the body{} rule (index.html owns body), and the a{color:inherit} rule
// (added for the standalone page's plain-text nav links; this embed has no
// <a> tags at all, only buttons). ----
function stripRule(css, selectorStart) {
  const i = css.indexOf(selectorStart);
  if (i === -1) return css;
  const braceStart = css.indexOf("{", i);
  let depth = 1, k = braceStart + 1;
  while (depth > 0 && k < css.length) {
    if (css[k] === "{") depth++;
    else if (css[k] === "}") depth--;
    k++;
  }
  return css.slice(0, i) + css.slice(k);
}
let css = rawCss;
css = stripRule(css, ":root{");
css = stripRule(css, "*{ box-sizing:border-box; }".split("{")[0] + "{"); // "*{"
css = stripRule(css, "body{");
css = stripRule(css, "a{ color:inherit; }".split("{")[0] + "{"); // "a{"

// ---- 3. Scope every selector under #page-bracket. Walk the CSS tracking
// brace depth so @media/@keyframes are told apart from plain rules. ----
function scopeSelectorList(selText) {
  return selText
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean)
    .map((s) => "#page-bracket " + s)
    .join(", ");
}

function scopeCss(cssText) {
  let out = "";
  let i = 0;
  while (i < cssText.length) {
    // Skip (copy verbatim) any run of whitespace, then any run of comments --
    // a comment almost never starts exactly at the top of the loop (there's
    // usually a blank line/indentation left over from the previous rule's
    // closing brace), so without this skip the whitespace-then-comment text
    // gets swept into the next rule's "prelude" below and mangled by
    // scopeSelectorList's naive comma-split (a comment's prose commas get
    // treated as selector-list separators). This was a real, shipped bug.
    let consumedAny = true;
    while (consumedAny) {
      consumedAny = false;
      const wsMatch = /^\s+/.exec(cssText.slice(i));
      if (wsMatch) { out += wsMatch[0]; i += wsMatch[0].length; consumedAny = true; }
      if (cssText.startsWith("/*", i)) {
        const end = cssText.indexOf("*/", i);
        const stop = end === -1 ? cssText.length : end + 2;
        out += cssText.slice(i, stop);
        i = stop;
        consumedAny = true;
      }
    }
    if (i >= cssText.length) break;
    const braceIdx = cssText.indexOf("{", i);
    if (braceIdx === -1) { out += cssText.slice(i); break; }
    const prelude = cssText.slice(i, braceIdx);
    // find matching close brace for this block
    let depth = 1, k = braceIdx + 1;
    while (depth > 0 && k < cssText.length) {
      if (cssText[k] === "{") depth++;
      else if (cssText[k] === "}") depth--;
      k++;
    }
    const inner = cssText.slice(braceIdx + 1, k - 1);
    const trimmedPrelude = prelude.trim();
    if (trimmedPrelude.startsWith("@keyframes")) {
      // Leave keyframes completely alone -- percentage selectors, and the
      // animation name other rules reference by exact string, must not change.
      out += prelude + "{" + inner + "}";
    } else if (trimmedPrelude.startsWith("@media")) {
      // Recurse: scope the rules INSIDE the media block, keep its condition as-is.
      out += prelude + "{" + scopeCss(inner) + "}";
    } else if (trimmedPrelude === "") {
      // stray brace / already consumed comment edge case -- copy through
      out += prelude + "{" + inner + "}";
    } else {
      out += scopeSelectorList(prelude) + " {" + inner + "}";
    }
    i = k;
  }
  return out;
}

const scopedCss = scopeCss(css);

// ---- 4. Declare the token aliases once, inherited by the whole subtree.
// Values match the prototype's own :root exactly (see that file's comment
// block) -- this is NOT a re-skin, it's routing the same names the CSS body
// already uses through to index.html's real theme variables (or, for the
// three tokens the site has no equivalent for, the prototype's own literal
// value, scoped so it can never leak to the rest of the app). ----
const ALIAS_CSS = `#page-bracket{
  --line: var(--border);
  --paper: var(--text);
  --surface-2: var(--surface2);
  --good: var(--accent);
  --bad: var(--accent2);
  --accent-2: #ffb340;
  --on-accent: #04140a;
  --shadow: 0 8px 24px rgba(0,0,0,0.4);
}
`;

const finalCss = ALIAS_CSS + scopedCss;

// ---- 5. Extract the body markup: the "This week: <division>" line down
// through the close of the results section. Deliberately SKIPS the
// prototype's own <h1>Legends Bracket</h1> + .tagline -- index.html's own
// scaffold around this block (see the "PAGE: LEGENDS BRACKET" comment)
// already gives it a standard .page-header-title, same as every other
// embedded page (Rankings, Active Roster, Tape Study, ...), so a second,
// bigger, differently-styled heading right under it would be redundant. ----
const bodyHtml = between(src, '<p class="subtitle">', "\n  <!-- CTA SLOT")
  .replace(/^/, '<p class="subtitle">');

// ---- 6. Extract the JS (the IIFE body between <script> and </script>).
// Left byte-for-byte except: the sticky-header selector showResults() uses
// to compute a scroll offset -- there is no ".lb-topbar" inside the SPA,
// its real sticky bar is ".site-header" (index.html's own top nav). ----
let js = between(src, "<script>\n(function(){", "})();\n</script>")
  .replace(/document\.querySelector\('\.lb-topbar'\)/, "document.querySelector('.site-header')");

// ---- 7. Splice into index.html between the three marker pairs the
// "PAGE: LEGENDS BRACKET" scaffold already carries (inserted once by hand;
// see that comment in index.html for why the scaffold itself isn't
// generated). Each replace is exact-string, so a missing/renamed marker
// throws immediately instead of silently no-op'ing. ----
function spliceBetween(doc, startMarker, endMarker, content) {
  const i = doc.indexOf(startMarker);
  if (i === -1) throw new Error("index.html marker not found: " + startMarker);
  const from = i + startMarker.length;
  const j = doc.indexOf(endMarker, from);
  if (j === -1) throw new Error("index.html end marker not found: " + endMarker + " (after " + startMarker + ")");
  return doc.slice(0, from) + "\n" + content + "\n" + doc.slice(j);
}

let target = fs.readFileSync(TARGET, "utf8");
target = spliceBetween(target, "<!-- BRACKET-EMBED:HTML:START -->", "<!-- BRACKET-EMBED:HTML:END -->", bodyHtml);
target = spliceBetween(target, "/* BRACKET-EMBED:CSS:START */", "/* BRACKET-EMBED:CSS:END */", finalCss);
target = spliceBetween(target, "// BRACKET-EMBED:JS:START", "// BRACKET-EMBED:JS:END", "(function(){\n" + js + "\n})();");
fs.writeFileSync(TARGET, target);
console.log("index.html: spliced bracket embed (html " + bodyHtml.length + " / css " + finalCss.length + " / js " + js.length + " chars) from " + fs.statSync(SRC).size + " bytes of prototype");
